using Rhino;using System.Text.Json;using System.IO;
namespace RhinoContextAssist;
internal sealed class ContextAssistSettings{
 readonly PersistentSettings store;public bool Enabled{get;set;}public bool AutomaticPrioritization{get;set;}public int PrimaryCount{get;set;}public PopupUxMode UxMode{get;set;}public PopupPositionMode PositionMode{get;set;}public int SelectionDelayMs{get;set;}public int HoverDelayMs{get;set;}public int CollapseDelayMs{get;set;}public int MoreCollapseDelayMs{get;set;}public int AutoHideMs{get;set;}public int CornerMarginPx{get;set;}public int IdleOpacity{get;set;}public int ActiveOpacity{get;set;}public List<ContextAction> CustomActions{get;}=new();public Dictionary<SelectionKind,List<ActionPreference>> Preferences{get;}=new();public Dictionary<string,UsageEntry> Usage{get;}=new();
 public ContextAssistSettings(PersistentSettings s){store=s;Load();}void Load(){Enabled=store.GetBool("Enabled",true);AutomaticPrioritization=store.GetBool("Auto",true);PrimaryCount=store.GetInteger("Primary",5);UxMode=store.GetEnumValue("Ux",PopupUxMode.Compact);PositionMode=store.GetEnumValue("Position",PopupPositionMode.AutoViewportCorner);SelectionDelayMs=store.GetInteger("SelectionDelay",300);HoverDelayMs=store.GetInteger("HoverDelay",300);CollapseDelayMs=store.GetInteger("Collapse",600);MoreCollapseDelayMs=store.GetInteger("MoreCollapse",1500);AutoHideMs=store.GetInteger("AutoHide",5000);CornerMarginPx=store.GetInteger("Margin",90);IdleOpacity=store.GetInteger("Idle",42);ActiveOpacity=store.GetInteger("Active",100);foreach(var k in ActionCatalog.Kinds)Preferences[k]=ActionCatalog.Defaults(k).Select(x=>new ActionPreference(x.Id,true,false)).ToList();try{CustomActions.AddRange(JsonSerializer.Deserialize<List<ContextAction>>(store.GetString("Custom","[]"))??new());}catch{}}
 public void Save(){store.SetBool("Enabled",Enabled);store.SetBool("Auto",AutomaticPrioritization);store.SetInteger("Primary",PrimaryCount);store.SetEnumValue("Ux",UxMode);store.SetEnumValue("Position",PositionMode);store.SetInteger("Margin",CornerMarginPx);store.SetString("Custom",JsonSerializer.Serialize(CustomActions));foreach(var p in Preferences)store.SetString("Preferences."+p.Key,JsonSerializer.Serialize(p.Value));}
 internal IReadOnlyList<ContextAction> Order(SelectionKind k,List<ContextAction>a){if(!Preferences.TryGetValue(k,out var p))return a;var map=p.Select((x,i)=>new{x.Id,x.Enabled,x.Favorite,I=i}).ToDictionary(x=>x.Id);return a.Where(x=>!map.ContainsKey(x.Id)||map[x.Id].Enabled).OrderByDescending(x=>map.TryGetValue(x.Id,out var m)&&m.Favorite).ThenByDescending(x=>AutomaticPrioritization&&Usage.TryGetValue(x.Id,out var u)?u.Count:0).ThenBy(x=>map.TryGetValue(x.Id,out var m)?m.I:int.MaxValue).ToList();}
 public bool IsFavorite(SelectionKind k,string id)=>Preferences.TryGetValue(k,out var p)&&p.Any(x=>x.Id==id&&x.Favorite);public void ToggleFavorite(SelectionKind k,string id){if(!Preferences.TryGetValue(k,out var p))return;var i=p.FindIndex(x=>x.Id==id);if(i>=0)p[i]=p[i] with{Favorite=!p[i].Favorite};Save();}public long UsageCount(string id)=>Usage.TryGetValue(id,out var u)?u.Count:0;public void RecordUsage(string id){var n=DateTime.UtcNow;Usage[id]=Usage.TryGetValue(id,out var u)?u with{Count=u.Count+1,LastUsedUtc=n}:new(id,1,n);}
}
